package day7;

public class Program3_NumberTriangle {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		for(int r=1;r<=5;r++)
		{
			for (int sp=1;sp<r;sp++)
				System.out.print(" ");
			for(int c=1;c<=6-r;c++)
				System.out.print(c);
			System.out.println();
			
		
		
		
	 	        

		}
	}
}
		

	
		
		

	


